let fileContent = msg.payload;

let defaultResponse = {
    actionBio: "no collection",
    colorBio: "white",
    actionPaper: "no collection",
    colorPaper: "white",
    actionDomestic: "no collection",
    colorDomestic: "white"
};

if (!fileContent || typeof fileContent !== 'string') {
    node.status({ fill: "red", shape: "ring", text: "Invalid file content" });
    flow.set('boxStatus', defaultResponse);
    flow.set('upcomingSchedule', []);
    msg.payload = { ledPower: 0, status: defaultResponse };
    return msg;
}

let lines = fileContent.split(/\r?\n/);
let events = [];
let currentEvent = null;

for (let line of lines) {
    if (line.startsWith('BEGIN:VEVENT')) {
        currentEvent = {};
    } else if (line.startsWith('END:VEVENT') && currentEvent) {
        events.push(currentEvent);
        currentEvent = null;
    } else if (currentEvent) {
        let splitIdx = line.indexOf(':');
        if (splitIdx !== -1) {
            let key = line.substring(0, splitIdx).trim();
            let val = line.substring(splitIdx + 1).trim();
            currentEvent[key] = val;
        }
    }
}

let today = new Date();
let tomorrow = new Date(today);
tomorrow.setDate(today.getDate() + 1);

let formatDateStr = (d) => {
    let y = d.getFullYear();
    let m = String(d.getMonth() + 1).padStart(2, '0');
    let dayStr = String(d.getDate()).padStart(2, '0');
    return `${y}${m}${dayStr}`;
};

let tomorrowStr = formatDateStr(tomorrow);

let getEventDate = (ev) => {
    if (!ev.DTSTART) return "";
    if (ev.DTSTART.includes(':')) {
        return ev.DTSTART.split(':').pop().trim();
    }
    return ev.DTSTART.split('T')[0];
};

let upcomingEventsForTomorrow = events.filter(ev => getEventDate(ev) === tomorrowStr);

let activeResponse = { ...defaultResponse };
let ledState = 0;

if (upcomingEventsForTomorrow.length > 0) {
    ledState = 1;
    node.status({ fill: "green", shape: "dot", text: `Morgen Abholung! (${upcomingEventsForTomorrow.length})` });

    for (let ev of upcomingEventsForTomorrow) {
        let summary = (ev.SUMMARY || "").toLowerCase();
        if (summary.includes('biomüll') || summary.includes('bio')) {
            activeResponse.actionBio = "take out the trash - biomüll";
            activeResponse.colorBio = "green";
        }
        if (summary.includes('papier')) {
            activeResponse.actionPaper = "take out the trash - papier";
            activeResponse.colorPaper = "yellow";
        }
        if (summary.includes('restmüll')) {
            activeResponse.actionDomestic = "take out the trash - restmüll";
            activeResponse.colorDomestic = "red";
        }
    }
} else {
    node.status({ fill: "yellow", shape: "ring", text: "Keine Abholung morgen" });
    ledState = 0;
}

flow.set('boxStatus', activeResponse);

// Build 7-day pulsating schedule (Blue exclusively for no collection)
let nextWeekSchedule = [];
for (let i = 1; i <= 7; i++) {
    let checkDate = new Date(today);
    checkDate.setDate(today.getDate() + i);
    let targetStr = formatDateStr(checkDate);

    let dayEvents = events.filter(ev => getEventDate(ev) === targetStr);
    let dayTypes = dayEvents.map(ev => ev.SUMMARY || "Unknown");

    let dayColor = "blue"; 
    if (dayTypes.some(t => t.toLowerCase().includes('bio'))) dayColor = "green";
    else if (dayTypes.some(t => t.toLowerCase().includes('papier'))) dayColor = "yellow";
    else if (dayTypes.some(t => t.toLowerCase().includes('restmüll'))) dayColor = "red";

    nextWeekSchedule.push({
        date: `${checkDate.getFullYear()}-${String(checkDate.getMonth() + 1).padStart(2, '0')}-${String(checkDate.getDate()).padStart(2, '0')}`,
        dayOffset: i,
        collections: dayTypes.length > 0 ? dayTypes : ["no collection"],
        pulsatingIndicatorColor: dayColor
    });
}

flow.set('upcomingSchedule', nextWeekSchedule);

msg.payload = {
    ledPower: ledState,
    status: activeResponse,
    nextWeek: nextWeekSchedule
};
return msg;

let data = msg.payload.status || {};
let activeLEDColor = "blue"; 
let targetDescription = "No trash scheduled for tomorrow (Blue LED)";

if (data.colorBio === "green") {
    activeLEDColor = "green";
    targetDescription = "Target: Biomüll (Green LED)";
} else if (data.colorPaper === "yellow") {
    activeLEDColor = "yellow";
    targetDescription = "Target: Papier (Yellow LED)";
} else if (data.colorDomestic === "red") {
    activeLEDColor = "red";
    targetDescription = "Target: Restmüll (Red LED)";
}

msg.payload = {
    simulationTarget: targetDescription,
    simulatedLedColor: activeLEDColor,
    timestamp: new Date().toISOString()
};

return msg;

let reqBody = msg.payload || {};
let isReset = reqBody.reset === true || reqBody.action === "reset" || reqBody.color === "white";

let currentStatus = flow.get('boxStatus') || {
    actionBio: "no collection", colorBio: "white",
    actionPaper: "no collection", colorPaper: "white",
    actionDomestic: "no collection", colorDomestic: "white"
};

if (isReset) {
    currentStatus = {
        actionBio: "no collection", colorBio: "white",
        actionPaper: "no collection", colorPaper: "white",
        actionDomestic: "no collection", colorDomestic: "white"
    };
    flow.set('boxStatus', currentStatus);
}

msg.payload = currentStatus;
return msg;

let schedule = flow.get('upcomingSchedule') || [];
msg.payload = {
    schedule: schedule
};
return msg;
